# -*- coding: utf-8 -*-
"""
Oam factory
"""
from builtins import object
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler
from taf.ul.trs_e2e_fw.lib.oam.admin.admin_interface import AdminInterface
from taf.ul.trs_e2e_fw.lib.oam.btssm.btssm_interface import BtssmInterface
from taf.ul.trs_e2e_fw.lib.oam.mzoam.mzoam_interface import MzoamInterface
from taf.ul.trs_e2e_fw.lib.oam.coam_cbts_cu.coam_cu_interface import CoamCUInterface
from taf.ul.trs_e2e_fw.lib.oam.coam_cbts_vdu.coam_vdu_interface import CoamVDUInterface
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class OamFactory(object):
    """
    Oam Factory
    """
    def __init__(self):
        self.config = ConfigHandler.get_config()

    def get_instance(self, dut):
        """
        Get Instance
        """
        if self._is_bts_a_cbts(dut) is "vcu":
            return CoamCUInterface()
        elif self._is_bts_a_cbts(dut) is "vdu":
            return CoamVDUInterface()
        else:
            oam_tool = self.config[dut].get('oam_tool', 'admin')
            if oam_tool.lower() == 'admin':
                logger.debug("env is admin")
                return AdminInterface()
            elif oam_tool.lower() == 'btssm':
                logger.debug("env is btssm")
                return BtssmInterface()
            elif oam_tool.lower() == 'mzoam':
                return MzoamInterface()

    def _is_bts_a_cbts(self, dut):
        # Automatic way to be checked
        # Check for "cu_version" instead in the config[dut].keys()
        if "oam" in list(self.config[dut].keys()):
            logger.debug("printing dut:  {} \n{}".format(dut, self.config[dut]))
            if self.config[dut]["cloud_module"] == "vdu":
                logger.debug("dut passed is VDU")
                return "vdu"
            else:
                logger.debug("dut passed is CU")
                return "vcu"
        logger.debug("dut passed is BTS")
        return False
